232:   private processRoles(): void {
233:     const defaultOptions = [
234:       {
235:         Id: environment.UNIDADES_EJECUTORAS.RECTORIA,
236:         Nombre: 'Rectoría',
237:       },
238:       {
239:         Id: environment.UNIDADES_EJECUTORAS.IDEXUD,
240:         Nombre: 'IDEXUD',
241:       },
242:     ];
243: 
244:     const filteredRoles = this.roles.filter(
245:       (role) => role.includes('RECTOR') || role.includes('IDEXUD')
246:     );
247: 
248:     if (filteredRoles.length === 0) {
249:       this.unidadesEjecutoras = defaultOptions;
250:       this.formInfoGeneral.patchValue({
251:         unidadEjecutoraId: defaultOptions[0].Id.toString()
252:       });
253:       return;
254:     }
255: 
256:     const mappedItems = filteredRoles
257:       .map((role) => {
258:         if (role.includes('RECTOR')) {
259:           return {
260:             Id: environment.UNIDADES_EJECUTORAS.RECTORIA,
261:             Nombre: 'Rectoría',
262:           };
263:         }
264:         if (role.includes('IDEXUD')) {
265:           return {
266:             Id: environment.UNIDADES_EJECUTORAS.IDEXUD,
267:             Nombre: 'IDEXUD',
268:           };
269:         }
270:         return null;
271:       })
272:       .filter((item): item is SimpleItem => item !== null);
273: 
274:     const uniqueMap = new Map(mappedItems.map((item) => [item.Id, item]));
275:     this.unidadesEjecutoras = Array.from(uniqueMap.values());
276: 
277:     if (this.unidadesEjecutoras.length === 1) {
278:       this.formInfoGeneral.patchValue({
279:         unidadEjecutoraId: this.unidadesEjecutoras[0].Id.toString()
280:       });
281:     }
282:   }
