406:   //Especificos
407:   showFieldsBasedOnCompromiso(id_compromiso: string) {
408:     const idCompromisoStr = id_compromiso.toString();
409: 
410:     this.showContratoFields =
411:       idCompromisoStr === environment.CONTRATO_ID ||
412:       idCompromisoStr === environment.ORDEN_ID;
413:     this.showConvenioFields = idCompromisoStr === environment.CONVENIO_ID;
414: 
415:     const convenioFields = ['vigenciaConvenio', 'convenio', 'nombreConvenio'];
416: 
417:     [
418:       ...convenioFields,
419:       'perfilContratistaId',
420:       'aplicaPoliza',
421:       'fechaSuscripcionEstudios',
422:     ].forEach((field) => {
423:       const control = this.formInfoGeneral.get(field);
424:       if (control) {
425:         control.reset();
426:         if (this.showConvenioFields && convenioFields.includes(field)) {
427:           control.setValidators(Validators.required);
428:           control.enable();
429:         } else {
430:           control.clearValidators();
431:           control.disable();
432:         }
433:         control.updateValueAndValidity();
434:       }
435:     });
436: 
437:     this.cdRef.detectChanges();
438:   }
