14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path!: any;
19:   public httpOptions: any;
20:   constructor(private http: HttpClient, private errManager: HttpErrorManager) {
21:     const acces_token = window.localStorage.getItem('access_token');
22:     if (acces_token !== null) {
23:       this.httpOptions = {
24:          headers: new HttpHeaders({
25:            'Content-Type': 'application/json',
26:            'Authorization': `Bearer ${acces_token}`,
27:          }),
28:       }
29:     }
30:   }
31: 
32: 
33:   /**
34:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
35:    * @param service: string
36:    */
37:   public setPath(service: string) {
38:     this.path = environment[service as keyof typeof environment];
39:   }
40: 
41: 
42:   /**
43:    * Perform a GET http request
44:    * @param endpoint service's end-point
45:    * @param params (an Key, Value object with que query params for the request)
46:    * @returns Observable<any>
47:    */
48:   get(endpoint: any) {
49: 
50:     return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
51:       map(
52:         (res) => {
53:           if (res.hasOwnProperty('Body')) {
54:             return res;
55:           } else {
56:             return res;
57:           }
58:         },
59:       ),
60:       catchError(this.errManager.handleError.bind(this)),
61:     );
62:   }
63: 
64:   /**
65:    * Perform a POST http request
66:    * @param endpoint service's end-point
67:    * @param element data to send as JSON
68:    * @returns Observable<any>
69:    */
70:   post(endpoint: any, element: any) {
71:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
72:       catchError(this.errManager.handleError),
73:     );
74:   }
75: 
76:   /**
77:    * Perform a POST http request
78:    * @param endpoint service's end-point
79:    * @param element data to send as JSON
80:    * @returns Observable<any>
81:    */
82:   post_file(endpoint: any, element: any) {
83:     return this.http.post<any>(`${this.path}${endpoint}`, element, {    headers: new HttpHeaders({
84:       'Content-Type': 'multipart/form-data',
85:   })}).pipe(
86:       catchError(this.errManager.handleError),
87:     );
88:   }
89: 
90:   /**
91:    * Perform a PUT http request
92:    * @param endpoint service's end-point
93:    * @param element data to send as JSON, With the id to UPDATE
94:    * @returns Observable<any>
95:    */
96:   put(endpoint: any, element: { Id: any; }) {
97:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
98:     return this.http.put<any>(path, element, this.httpOptions).pipe(
99:       catchError(this.errManager.handleError),
100:     );
101:   }
102: 
