258:   async aprobarAuditoria(estados: number[], mensajeAprobacion: string) {
259:     // La firma se hace antes del cambio de estado para que el informe final no quede aprobado sin firmar
260:     if (estados.includes(environment.AUDITORIA_ESTADO.EJECUCION.APROBADO_INFORME_FINAL_JEFE)) {
261:       try {
262:         await this.firmarInformeFinal();
263:       } catch (error) {
264:         console.error(error);
265:         this.alertService.showErrorAlert(
266:           `Error al firmar electrónicamente el Informe final. ${this.obtenerMensajeErrorFirma(error)}`
267:         );
268:         return;
269:       }
270:     }
271: 
272:     try {
273:       for (const estado of estados) {
274:         const auditoriaEstado = this.construirObjetoAuditoriaEstado(estado);
275:         await this.planAuditoriaService.post("auditoria-estado", auditoriaEstado).toPromise();
276:       }      
277: 
278:       if (estados.includes(environment.AUDITORIA_ESTADO.EJECUCION.APROBADO_PREINFORME_JEFE)) {
279:         await this.guardarFechaRevisionPreinforme();
280:       }
281: 
282:       let selladoConFallos = false;
283:       if (estados.includes(environment.AUDITORIA_ESTADO.EJECUCION.APROBADO_INFORME_FINAL_JEFE)) {
284:         await this.guardarFechaAprobacionInformeFinal();
285:         selladoConFallos = !(await this.sellarNumeracionHallazgos());
286:         await this.crearCascaronPlanMejoramiento();
287:       }
288: 
289:       const mensaje = this.estadoAuditoriaId === environment.AUDITORIA_ESTADO.EJECUCION.REVISION_INFORME_FINAL_JEFE
290:         ? "Informe final enviado"
291:         : "Informe preliminar enviado";
292:       await this.alertService.showSuccessAlert(mensajeAprobacion, mensaje);
293:       if (selladoConFallos) {
294:         await this.alertService.showNotification(
295:           "Aviso",
296:           "La numeración de hallazgos no pudo completarse."
297:         );
298:       }
299:       this.router.navigate([`/ejecucion/auditorias-internas/`]);
300:     } catch (error) {
301:       this.alertService.showErrorAlert("Error al aprobar el informe.");
302:     }
