314:       firstValueFrom(this.tercerosService.getAuthenticatedUserTerceroResponse().pipe(
315:         throwIfEmpty(() => new Error("No se encontró la información del firmante."))
316:       )),
317:       firstValueFrom(this.planAuditoriaMid.get(`auditoria/${this.auditoriaId}`)),
318:     ]);
