320:     const [documentoInforme] = this.referenciaPdfService.filtrarValidos(documentos);
321:     if (!documentoInforme)
322:       throw new Error("No se encontró el Informe final de la auditoría.");
323: 
324:     // Si el informe ya fue firmado en una aprobación anterior se firma el original para no duplicar firmas
325:     const enlaceSinFirma = documentoInforme.metadatos?.["firmado"]
326:       ? documentoInforme.metadatos?.["nuxeo_enlace_sin_firma"] ?? documentoInforme.nuxeo_enlace
327:       : documentoInforme.nuxeo_enlace;
328: 
329:     const base64 = await this.nuxeoService.obtenerPorUUID(enlaceSinFirma);
