339:       descripcion: "Informe final de auditoría firmado electrónicamente por el Jefe OCI",
340:       metadatos: {
341:         auditoria_id: this.auditoriaId,
342:         consecutivo_oci: consecutivoOci,
343:         vigencia: auditoria?.vigencia_nombre ?? String(auditoria?.vigencia_id ?? ""),
344:       },
345:       firmantes: [
346:         {
347:           nombre: jefe.Tercero.NombreCompleto,
348:           cargo: "Jefe Oficina de Control Interno",
349:           oficina: "Oficina de Control Interno",
350:           tipoId: jefe.Identificacion?.TipoDocumentoId?.CodigoAbreviacion ?? "CC",
351:           identificacion: jefe.Identificacion?.Numero,
352:         },
353:       ],
354:       representantes: [],
355:       file: base64,
356:     };
